import type { LessonExpansion } from '../types.ts';
import {chapter,reasoning} from './basics-helpers.ts';
export const generalExpansions: Record<string, LessonExpansion> = {
'preparar-concurso':chapter('preparar-concurso',[
 ['Un ensayo que se parece al día real','Prepara un simulacro de 90 minutos con tres ejercicios locales que todavía no hayas resuelto. Dedica los primeros diez minutos a leerlos todos, reconocer entradas y límites y estimar cuál puedes explicar con más seguridad. Reserva los últimos quince para revisar. Durante el ensayo no consultes soluciones; al terminar sí puedes estudiarlas. Así separas dos habilidades: decidir bajo tiempo limitado y aprender ideas nuevas sin presión.'],
 ['Una hoja de decisiones','Anota para cada problema una idea, su costo y el siguiente paso comprobable. «No me sale» no indica qué hacer; «mi ciclo cuenta parejas dos veces» sí sugiere revisar índices. Si pasan quince minutos sin una nueva observación, cambia de problema y deja una nota que te permita retomar. No existe una regla universal de minutos: aprende de tus simulacros qué señales anuncian que estás repitiendo intentos sin información nueva.'],
 ['Al terminar también se entrena','Clasifica cada dificultad como comprensión, idea, implementación o manejo del tiempo. Elige una corrección concreta para la siguiente sesión. Haber resuelto menos ejercicios de los esperados no define tu capacidad: es información sobre qué practicar. Revisa también sueño, agua y pausas; llegar con cansancio puede ocultar habilidades que sí tienes. Si participas en un evento oficial, consulta su convocatoria vigente para horarios y materiales permitidos; la práctica de esta página no exige inscribirte.']
 ],[reasoning('reparto-tiempo','Planea noventa minutos','Tienes tres problemas. A parece directo, B necesita una idea que aún no entiendes y C tiene una solución lenta que puedes explicar. Diseña un orden de trabajo y una condición concreta para cambiar de problema.',['Distingue certeza de dificultad aparente.','Reserva tiempo para verificar, no solo para escribir.'],'Una estrategia razonable es leer los tres, resolver A y verificarlo; después explorar C, donde ya existe una base, mientras guardamos B para una nueva lectura. Si en C no encontramos una mejora después de una exploración con ejemplos y límites, anotamos la barrera y pasamos a B. No es una receta obligatoria: el valor está en conservar avances, evitar ciclos improductivos y reservar una revisión final.'),reasoning('retrospectiva','Convierte un fallo en entrenamiento','En un simulacro resolviste la idea correcta pero fallaste porque n = 1 accedía a una posición inexistente. Escribe una tarea de diez minutos para evitar repetir ese error.',['La tarea debe ser comprobable.','Incluye el tamaño mínimo y una explicación de los índices.'],'Reescribe el recorrido marcando los índices válidos: 0 hasta n − 1. Prueba n = 1, n = 2 y un caso normal, anotando cada acceso. Explica por qué cada índice queda dentro del intervalo y revisa las expresiones i + 1. El hábito que buscamos es vincular límites con accesos; resolver al azar diez ejercicios más no ataca necesariamente esta causa.')]),
'usaco-general-using-this-guide':chapter('usaco-general-using-this-guide',[
 ['Una sesión completa dentro de la guía','Elige una lección cuyos requisitos puedas explicar. Lee una sección, predice el ejemplo y ejecútalo con una entrada diferente. Después intenta el primer ejercicio sin abrir las pistas. Si te detienes, revela una pista y escribe qué observación nueva te dio. Al terminar compara tu explicación con la solución y registra una duda en tus apuntes. La lectura, el laboratorio, las pistas y las soluciones están disponibles aquí.'],
 ['Avanzar no significa saltarse dudas','Si la explicación utiliza una idea desconocida, vuelve al requisito correspondiente y trabaja un ejemplo pequeño. No necesitas dominar toda una etapa para experimentar con un tema posterior, pero una dificultad repetida suele señalar un hueco concreto. Una lección de veinte minutos puede requerir varias sesiones; el tiempo estimado no mide tu inteligencia. Marca el avance cuando puedas reconstruir la idea, no únicamente cuando llegues al final de la página.'],
 ['Cómo saber si ya lo entendiste','Comprueba tres capacidades: explicar qué problema resuelve el método, ejecutarlo a mano con datos nuevos y justificar por qué funciona. Añade una prueba de frontera. Si puedes repetir código pero no responder por qué el ciclo termina, vuelve a esa parte. Los enlaces de fuentes quedan como consulta opcional; no son una tarea obligatoria ni requieren inglés para completar la ruta local. Tu progreso y tus borradores se conservan en este navegador.']
 ],[reasoning('sesion','Diseña una sesión de media hora','Tienes treinta minutos y quieres estudiar ciclos. Distribuye lectura, predicción, ejecución y práctica. Explica qué harás si el primer ejercicio no sale.',['Incluye tiempo sin mirar la solución.','Una pista puede servir para retomar, no para ocultar una duda.'],'Una distribución posible es cinco minutos de lectura, cinco de traza manual, diez para el ejercicio y diez para probar y explicar. Si nos detenemos, anotamos el estado del contador y abrimos una pista; después cerramos la solución y retomamos. La sesión termina con una explicación breve y una duda identificada, incluso si hace falta continuar otro día.'),reasoning('dominio','¿Terminé la lección?','Ana copió un programa que pasó las pruebas. Bruno escribió uno que falla para cero datos, pero sabe explicar su recorrido. ¿Qué debe hacer cada quien antes de considerar dominado el tema?',['Pasar pruebas y comprender son evidencias distintas.','Una solución correcta también necesita cubrir sus límites.'],'Ana debe reconstruir la idea sin copiar, predecir otro caso y explicar cada parte necesaria. Bruno debe corregir el caso vacío y justificar que el arreglo cubre todos los tamaños admitidos. Ninguno está excluido del aprendizaje: cada uno tiene un siguiente paso distinto. El dominio combina comprensión, implementación y revisión de las condiciones del problema.')]),
'usaco-general-intro-cp':chapter('usaco-general-intro-cp',[
 ['Qué revisa un juez','Un juez prepara muchas entradas válidas, ejecuta tu programa con cada una y compara la salida esperada. Puede limitar tiempo y memoria. No lee tus intenciones: un programa que responde bien a un ejemplo puede fallar en otro. Tampoco exige una redacción idéntica de código: varios algoritmos correctos pueden producir la misma respuesta. Aquí las pruebas de los ejercicios te ayudan a comprobar ejemplos; tu explicación cubre por qué la idea debe funcionar en general.'],
 ['Un problema completo en miniatura','Supón que recibes la capacidad c de una sala y la cantidad p de asistentes. Debes responder SI cuando p ≤ c y NO en otro caso. La historia se convierte en dos datos y una comparación. Prueba p = c, porque la igualdad forma parte de la aceptación. No necesitas una aplicación con botones ni una base de datos: un programa corto puede representar exactamente la tarea matemática.'],
 ['Competir también es investigar','Primero buscamos una solución correcta, aunque sea lenta. Luego contamos operaciones y aprovechamos los límites para decidir si necesitamos mejorarla. Esta secuencia enseña a construir y revisar argumentos. Un resultado de concurso no es un juicio sobre quién puede aprender a programar. Entrenar consiste en reconocer patrones, hacer preguntas precisas y estudiar errores; los ejercicios locales permiten practicar esas habilidades sin inscripción ni conocimiento de inglés.']
 ],[reasoning('juez','Un ejemplo no es una demostración','Un programa responde siempre 10. Pasa el ejemplo de un problema que pide sumar dos números porque ese ejemplo contiene 4 y 6. Da una entrada que lo refute y explica qué debería hacer la solución general.',['Busca una pareja cuya suma no sea 10.','El programa debe depender de los datos recibidos.'],'La entrada 1 2 exige 3, de modo que responder 10 falla. La solución general lee ambos números y suma sus valores, en lugar de memorizar la muestra. Un ejemplo confirma una ejecución particular; una explicación del algoritmo establece la relación entre cualquier entrada válida y su respuesta.'),reasoning('criterios','Correcto, rápido y con formato','Compara tres soluciones para sumar n números: A los suma correctamente pero imprime una frase adicional; B imprime el formato correcto pero olvida el último; C suma todos y escribe únicamente el total. ¿Qué revisas antes de enviar C?',['La corrección incluye los n valores.','Revisa también rango numérico y costo.'],'A puede fallar por salida extra y B por omitir un dato. En C comprobamos que el acumulador soporte la suma máxima, que n = 1 funcione y que el ciclo lea exactamente n números. Su tiempo O(n) es natural porque debe examinar cada entrada. La salida correcta, el algoritmo y los límites son partes del mismo contrato.')]),
'usaco-general-choosing-lang':chapter('usaco-general-choosing-lang',[
 ['Una elección para esta ruta','Aquí trabajaremos con C++17 porque permite expresar los algoritmos de toda la ruta y ejecutar ejemplos en el laboratorio integrado. No necesitas instalarlo ni estudiar otro idioma de programación primero. Si ya conoces Python, puedes comparar conceptos, pero intenta no mezclar la sintaxis dentro del mismo programa. Variables, ciclos, funciones y estructuras son ideas transferibles; su escritura concreta cambia entre lenguajes.'],
 ['Aprender lo necesario en orden','Comienza por leer y escribir números, después decisiones y repeticiones, luego secuencias y funciones. No necesitas dominar punteros, herencia ni plantillas para resolver tus primeros problemas. La biblioteca estándar ofrece vector, string, sort, set y map; cada herramienta aparece cuando hay un problema que la justifica. Memorizar una lista de palabras reservadas sin usarlas produce menos comprensión que modificar un programa pequeño y predecir sus resultados.'],
 ['Qué hacer cuando un ejemplo no compila','Comprueba primero que sea C++ y que incluya un programa completo con main. Algunos artículos muestran fragmentos que deben colocarse dentro de otra función; los ejemplos ejecutables de esta guía incluyen su contexto. El laboratorio usa C++17 y una biblioteca limitada al entorno de navegador: un programa que requiere extensiones particulares de una plataforma podría necesitar adaptación. Para aprender algoritmos usaremos estructuras estándar y evitaremos depender de herramientas externas.']
 ],[reasoning('ruta','Prioriza conceptos','Quieres resolver un problema que suma las edades de n estudiantes. Ordena lo que necesitas aprender: entrada, acumulador, ciclo, herencia, gráficos y salida. Justifica qué puedes posponer.',['Identifica las operaciones de la tarea.','No toda característica de un lenguaje es un requisito inicial.'],'Necesitamos leer n y las edades, mantener una suma, repetir la lectura y escribir el resultado. Herencia y gráficos no participan en esa transformación de datos, por lo que pueden posponerse. Elegir un lenguaje no obliga a aprenderlo entero antes de resolver problemas; construimos un repertorio a partir de necesidades concretas.'),reasoning('transferencia','La idea sobrevive al lenguaje','Una persona explica: «empiezo con total cero; por cada número lo agrego; al final muestro total». ¿Qué parte de esa explicación depende de C++? ¿Qué falta decidir al implementarla?',['Separa algoritmo de sintaxis.','Piensa en el tipo de dato y en cómo sabemos cuántos números llegan.'],'La idea de acumulación no depende de C++; puede expresarse en muchos lenguajes. Al implementarla decidimos el formato de entrada, el número de iteraciones, el tipo capaz de guardar el total y la instrucción de salida. La sintaxis cambia, pero el argumento de que total contiene la suma de lo ya leído permanece.')]),
'usaco-general-resources-learning-to-code':chapter('usaco-general-resources-learning-to-code',[
 ['Un mapa de las primeras habilidades','La secuencia inicial es mensajes, lectura, variables, decisiones, ciclos, arreglos, cadenas y funciones. Cada tema agrega una capacidad: los ciclos repiten una acción que ya sabes escribir, y los arreglos conservan varios datos que ya sabes leer. Si una explicación resulta difícil, identifica cuál de esas piezas no reconoces. Volver a ella con un ejemplo de cinco líneas suele ser más útil que empezar otro curso entero.'],
 ['Tres versiones de cada ejemplo','Primero ejecuta el programa tal como aparece y verifica que entiendes su entrada. Luego cambia un dato y predice la salida sin ejecutar. Finalmente cambia una regla: si contaba valores mayores que diez, haz que cuente los menores. Esta tercera versión revela si entendiste la condición o solamente repetiste el ejemplo. Guarda en tus apuntes qué cambiaste y por qué el resultado esperado es distinto.'],
 ['Una semana razonable para comenzar','Puedes dedicar una sesión a lectura y variables, otra a condicionales, dos a ciclos y otra a un ejercicio que combine ambas ideas. Distribuir el estudio permite volver a recordar sin mirar; esa reconstrucción es parte del aprendizaje. Si tienes poco tiempo, una sesión breve con una pregunta bien resuelta vale más que dejar una explicación abierta durante horas. La ruta local incluye ejemplos, práctica y soluciones para que no dependas de una búsqueda en inglés.']
 ],[reasoning('modificar','Modifica una regla con intención','Un programa cuenta números mayores que 10. Diseña una prueba que distinga esa regla de «al menos 10». Explica qué operador debe cambiar y cuál debería ser la nueva respuesta.',['Incluye exactamente el valor frontera.','Usa también un número a cada lado.'],'La lista 9, 10, 11 produce 1 con > 10 y 2 con >= 10. Cambiamos > por >= porque ahora también aceptamos la igualdad. Una lista como 1, 20, 30 no distinguiría ambas reglas; elegir la frontera nos permite comprobar la modificación concreta.'),reasoning('diagnostico','Encuentra el requisito faltante','Entiendes qué es un arreglo pero no puedes explicar por qué for (int i = 0; i < n; ++i) termina. ¿Debes memorizar el recorrido del arreglo o revisar otra lección? Diseña una actividad breve.',['El recorrido combina dos conceptos.','Prueba un n pequeño y registra i.'],'Conviene revisar ciclos. Para n = 3 anotamos i = 0, 1, 2 y luego comprobamos que 3 < 3 es falso. Después aplicamos esos valores a los índices del arreglo. Así resolvemos la pieza faltante y conectamos conceptos; memorizar el recorrido completo ocultaría la misma duda en el siguiente ejercicio.')]),
'usaco-general-running-code-online':chapter('usaco-general-running-code-online',[
 ['Qué sucede al pulsar ejecutar','El editor entrega el texto de C++ al compilador, que verifica su estructura y genera un programa ejecutable para el navegador. Después se inicia una ejecución con la entrada que escribiste. Compilar y ejecutar son etapas distintas: una coma faltante puede impedir la primera, mientras que una división entre cero ocurre durante la segunda. Lee el estado y el mensaje antes de modificar el código; te indican qué clase de problema investigar.'],
 ['Trabaja con una entrada completa','Si el programa lee n y después n números, para n = 3 debes escribir los tres valores. El panel de entrada equivale a un archivo preparado, no a una conversación que espera preguntas. Para comparar dos casos, sustituye la entrada y vuelve a ejecutar desde el principio. Una variable no conserva el valor de la ejecución anterior. El borrador del editor sí puede guardarse, pero ese texto persistente es distinto de la memoria temporal del programa.'],
 ['Los límites también forman parte del laboratorio','Un ciclo infinito o una salida interminable se detiene al alcanzar los límites del entorno. Eso protege la sesión y no significa que debas evitar experimentar: reduce el ejemplo y revisa qué condición debería terminar. El primer uso puede tardar mientras se cargan herramientas del compilador; las ejecuciones posteriores aprovechan la caché del navegador. Cerrar o recargar normalmente conserva el borrador. Borrar los datos del sitio o terminar una sesión privada puede eliminarlo; una copia descargada permite conservarlo también fuera de este navegador.']
 ],[reasoning('etapas','Identifica dónde ocurrió el fallo','Clasifica estos casos: falta una comilla; el programa intenta acceder a a[n]; la salida es correcta salvo una etiqueta extra; un while nunca modifica su condición. Indica qué evidencia buscarías en cada uno.',['No todos los errores se detectan al compilar.','Un programa puede terminar y aun así responder mal.'],'La comilla faltante es un error de compilación. El acceso inválido puede causar un error de ejecución o comportamiento indefinido. La etiqueta extra es un problema de formato aunque el programa termine. El while puede provocar un límite de tiempo; necesitamos revisar la actualización que debía acercarlo al final. Clasificar la etapa dirige la búsqueda hacia una causa concreta.'),reasoning('entrada','Prepara los datos','Tu programa lee n y suma n números. Escribe una entrada completa para sumar 2, −5 y 9 y predice el resultado. Explica por qué escribir solamente esos tres números no respeta el formato.',['El primer número representa la cantidad.','Después deben aparecer exactamente los datos que anuncia n.'],'La entrada correcta es 3 seguida de 2 −5 9. La suma es 6. Si escribiéramos solamente 2 −5 9, el programa interpretaría 2 como la cantidad y sumaría los dos valores siguientes, obteniendo 4. La misma secuencia de caracteres adquiere significado según el contrato de lectura; por eso el formato debe estar claro antes de ejecutar.')]),
'usaco-general-expected-knowledge':chapter('usaco-general-expected-knowledge',[
 ['Una evaluación que puedes hacer sin ayuda','Intenta leer cinco números, encontrar el mayor y contar cuántas veces aparece. Necesitas entrada, un recorrido, una comparación y variables que conserven información. No hace falta una estructura avanzada. Haz una traza con 3, 8, 8, 1, 5: el máximo es 8 y aparece dos veces. Explica qué reinicias cuando aparece un nuevo máximo y qué aumentas cuando encuentras otro igual.'],
 ['Matemáticas que sí usaremos','Debes sentirte cómodo con operaciones enteras, divisibilidad, comparaciones e intervalos. El símbolo n representa una cantidad variable, no un número misterioso. La notación 0 ≤ i < n indica posiciones válidas cuando contamos desde cero. Verás potencias para contar subconjuntos y logaritmos para procesos que reducen el tamaño repetidamente, pero se explicarán con ejemplos al necesitarlos. No necesitas cálculo diferencial para comenzar Bronce.'],
 ['El permiso para avanzar','No exigimos escribir todo sin errores: exigimos reconocerlos y saber reducir una duda. Si puedes leer un problema pequeño, inventar casos, programar una solución y explicar sus límites, tienes una base para seguir. Si fallas en un punto, practica esa habilidad con los ejercicios iniciales. Una lista de requisitos sirve para orientar el repaso, no para convertir el aprendizaje en un examen de memoria.']
 ],[reasoning('maximo','Traza un máximo con frecuencia','Recorre 5, 2, 7, 7, 3. Después de cada valor registra máximo y frecuencia. Explica qué sucede al leer el primer 7 y el segundo.',['Un valor mayor reemplaza al candidato anterior.','Una igualdad aumenta solamente la frecuencia.'],'Los estados son (5,1), (5,1), (7,1), (7,2), (7,2). El primer 7 crea un máximo nuevo y por eso reinicia la frecuencia en uno; el segundo coincide con el máximo y la aumenta. Conservar la frecuencia de 5 al cambiar de máximo mezclaría cantidades de valores diferentes.'),reasoning('requisitos','Diseña tu repaso','Puedes escribir condicionales, pero al recorrer un arreglo de tamaño n usas i <= n y a veces falla. Explica qué concepto necesitas repasar y crea dos pruebas mínimas.',['Relaciona cantidad de elementos con último índice.','n = 1 ya puede mostrar el error.'],'Necesitamos revisar índices desde cero y condición del ciclo. Para n = 1 solo existe a[0], pero i <= n también intenta a[1]. Para n = 2 existen a[0] y a[1], pero intenta a[2]. La condición correcta es i < n. El repaso debe conectar la desigualdad con el conjunto de posiciones válidas.')]),
'usaco-general-contributing':chapter('usaco-general-contributing',[
 ['Una contribución empieza por un problema concreto','Puedes mejorar material educativo aunque todavía aprendas algoritmos: detectar una palabra ambigua, una entrada mal formada o un ejemplo sin explicación es valioso. Describe lo que observaste, dónde ocurre y qué esperabas. «No entiendo nada» expresa frustración; «el ejemplo salta de suma 4 a suma 11 sin mostrar el dato 7» permite corregir una parte específica. No necesitas publicar nada para practicar esta revisión.'],
 ['Propón una edición verificable','Copia el fragmento breve que necesita cambiar en tus apuntes y escribe una versión que conserve la idea. Después comprueba el ejemplo a mano. Si corriges una fórmula, revisa que las palabras, el código y la respuesta concuerden. Un cambio pequeño con evidencia clara es más sencillo de revisar que reemplazar todo un capítulo sin explicar qué problema resuelve. Separa preferencias de estilo de errores de contenido.'],
 ['Cuida a quien aprende','Una explicación debe introducir los símbolos antes de usarlos y evitar suponer que alguien ya conoce una palabra técnica. Cuando añadas un recurso ajeno, identifica autor y licencia y respeta sus condiciones; una página pública no implica permiso irrestricto para copiarla. Para esta ruta creamos ejemplos y ejercicios propios. Revisar el material también enseña: obliga a convertir una intuición en una afirmación que otra persona pueda seguir.']
 ],[reasoning('reporte','Escribe un reporte útil','Una lección afirma que en [2,4,6] la suma es 11. Redacta un reporte con ubicación, error, resultado correcto y manera de verificarlo.',['Incluye la operación completa.','No necesitas descalificar a quien escribió el ejemplo.'],'Un reporte útil sería: «En el ejemplo del arreglo [2,4,6], el total aparece como 11. La suma correcta es 12, porque 2 + 4 = 6 y 6 + 6 = 12. Sugiero cambiar el total y revisar si el código o la prueba también usan 11». Identifica un hecho comprobable y una revisión relacionada, sin convertirlo en una crítica personal.'),reasoning('edicion','Haz explícita una suposición','El texto dice «recorre las posiciones válidas» sin definirlas. Reescríbelo para alguien que acaba de aprender vector. Explica qué ejemplo incluirías.',['Define el primer índice y el último.','Usa un tamaño pequeño.'],'Podemos escribir: «Si el vector tiene n elementos, sus índices son 0, 1, ..., n − 1. Para n = 3 visitamos 0, 1 y 2; el índice 3 queda fuera». Después mostramos la condición i < n. La edición no cambia el algoritmo, pero convierte una expresión vaga en un conjunto de posiciones que el estudiante puede verificar.')]),
'usaco-general-adding-solution':chapter('usaco-general-adding-solution',[
 ['La explicación debe resolver una pregunta','Una solución escrita comienza diciendo qué observación conecta la entrada con la respuesta. Para contar parejas distintas de n participantes, explicamos que cada pareja se identifica por dos índices i < j. Luego mostramos cómo enumerarlas o contarlas. Empezar con «usamos un for» describe una herramienta, pero todavía no explica por qué corresponde al problema. La idea debe poder entenderse antes de leer sintaxis.'],
 ['Un ejemplo que revele el método','Con cuatro participantes A, B, C y D, las parejas son AB, AC, AD, BC, BD y CD. Agruparlas por primer participante produce 3 + 2 + 1 = 6. El ejemplo muestra por qué no contamos BA de nuevo y por qué no incluimos AA. Después generalizamos a n(n − 1)/2. No hace falta un caso enorme: un ejemplo pequeño permite inspeccionar todas las posibilidades.'],
 ['Corrección y costo son preguntas distintas','La corrección explica que contamos cada pareja válida exactamente una vez. El costo describe cuánto trabajo usa la implementación: dos ciclos cuestan O(n²); la fórmula cuesta O(1). Si el producto puede superar int, debemos usar long long antes de multiplicar. Termina tu solución con casos frontera y límites. Así el lector sabe no solo qué escribir, sino cuándo es válida la implementación y qué errores debe evitar.']
 ],[reasoning('reescribir','Mejora una explicación insuficiente','Una solución dice «ordena y toma el primero». El problema pide el menor tiempo de una lista no vacía. Añade idea, corrección, costo y una alternativa.',['Explica qué garantiza el orden ascendente.','Buscar el mínimo no exige ordenar todos los elementos.'],'Al ordenar ascendentemente, cada elemento es al menos el anterior, por lo que el primero es el mínimo. Ordenar n elementos cuesta O(n log n). Sin embargo, podemos recorrer la lista conservando el menor visto: al terminar será el menor de todos y el tiempo será O(n). La solución debe mencionar que la lista no está vacía y permitir tiempos repetidos.'),reasoning('prueba','Explica parejas sin duplicarlas','Escribe una explicación de por qué los ciclos i = 0..n−1 y j = i+1..n−1 enumeran todas las parejas de posiciones diferentes exactamente una vez.',['Toda pareja tiene un índice menor y uno mayor.','El orden i < j elige una sola representación.'],'Para cualquier par de posiciones distintas, una es menor; la llamamos i y a la otra j. El ciclo exterior llega a i y el interior incluye ese j, así que la pareja aparece. Como siempre exigimos j > i, nunca aparece invertida ni con índices iguales. Esta cobertura y ausencia de duplicados justifican la enumeración completa.')]),
'usaco-general-modules':chapter('usaco-general-modules',[
 ['Diseña desde un objetivo observable','Un módulo no necesita abarcar todo lo relacionado con un tema. «Comprender arreglos» es amplio; «recorrer un vector y encontrar su mínimo sin salir de sus índices» puede comprobarse. Anota qué conocimientos presupone y un ejercicio final que use esa habilidad. Después construye la explicación que permita llegar a ese ejercicio. El orden importa: no uses una herramienta antes de presentarla o señalar claramente su requisito.'],
 ['La secuencia ejemplo, idea y generalización','Puedes empezar con [6,2,9] y buscar el menor a mano. Después explicas que conservamos el mejor candidato visto. Generalizas el recorrido, justificas el invariante y traduces a C++. Finalmente propones un caso con negativos y otro de tamaño uno. Cada paso responde una duda nueva; repetir la misma definición con otras palabras no reemplaza una traza o una justificación.'],
 ['Verifica autonomía y coherencia','Entrega el borrador a una persona imaginaria que solo conoce los requisitos. Comprueba que todos los símbolos estén definidos, que las entradas de los ejemplos sean completas y que la solución use el mismo formato que el enunciado. Un ejercicio debe poder intentarse sin abrir otro sitio. Las fuentes pueden ampliar el tema, pero el camino principal necesita contener las explicaciones y las respuestas necesarias para continuar.']
 ],[reasoning('esquema','Diseña una microlección','Propón el esquema de una lección para contar números pares. Incluye requisito, objetivo, ejemplo, idea, error frecuente y ejercicio final.',['La paridad se comprueba con residuo.','El ejercicio final debe usar datos nuevos.'],'Requisitos: lectura, ciclos y %. Objetivo: contar valores divisibles entre dos. Ejemplo: [3,4,8] produce 2. Idea: recorrer y aumentar un contador cuando x % 2 == 0. Error: sumar el valor par en lugar de contar una aparición. Ejercicio final: contar pares en una lista con cero y repetidos, justificando que cada posición se revisa una sola vez.'),reasoning('auditoria','Detecta un salto de dificultad','Una lección inicial explica sumar dos números y de inmediato pide encontrar el camino más corto en un grafo. ¿Qué falla en el diseño y cómo lo repararías?',['Revisa qué conceptos introduce el ejercicio sin explicación.','El objetivo debe conectar con la práctica.'],'El ejercicio requiere grafos, recorridos y posiblemente una estructura de cola que no se enseñaron. Para una lección de suma, el ejercicio debe variar el contexto o los límites de esa operación. El camino más corto pertenece a una secuencia posterior con representación de grafos y búsqueda. Reparar el diseño significa construir requisitos y ejemplos intermedios, no simplemente añadir una solución difícil al final.')]),
'usaco-general-working-mdx':chapter('usaco-general-working-mdx',[
 ['Contenido y presentación','Markdown representa estructuras con texto: un encabezado puede comenzar con #, una lista con guiones y un bloque de código con tres acentos graves. MDX combina ese texto con componentes de una aplicación. El objetivo educativo no es decorar cada oración, sino hacer visible la jerarquía entre idea, ejemplo y ejercicio. En esta guía el lector muestra secciones y laboratorios estructurados; no necesitas aprender MDX para estudiar algoritmos.'],
 ['Código que se puede copiar sin sorpresas','Indica el lenguaje del bloque y conserva comillas rectas, saltos y caracteres importantes. Si muestras solo un fragmento, di dónde se coloca; para un laboratorio autónomo es mejor proporcionar un programa completo con sus encabezados y main. El resultado esperado debe quedar separado del programa, porque copiar la salida dentro del código provoca errores. Un bloque visualmente atractivo también necesita compilar y corresponder al ejemplo escrito.'],
 ['Revisa enlaces y accesibilidad','Un enlace descriptivo expresa qué encontrará el lector; «haz clic aquí» depende demasiado del contexto. Una imagen educativa necesita una explicación textual de lo que aporta. No uses únicamente color para señalar una diferencia: acompáñalo con etiquetas o palabras. Si un componente interactivo falla, la idea central debería seguir disponible en texto. Esta revisión mejora la experiencia para estudiantes con diferentes dispositivos y formas de lectura.']
 ],[reasoning('estructura','Ordena una explicación','Tienes definición de ciclo, código, salida esperada, una advertencia sobre i <= n y un ejercicio. Propón una estructura de secciones que permita leer y probar sin confundir código con salida.',['Presenta la idea antes de la implementación.','La advertencia debe relacionarse con un ejemplo concreto.'],'Una estructura posible es: qué repite el ciclo; traza con n = 3; programa completo; salida esperada; frontera < frente a <=; ejercicio. El código y la salida se presentan en bloques diferentes y cada uno tiene una etiqueta. Así el lector puede anticipar el resultado y después comparar sin copiar accidentalmente texto explicativo dentro del programa.'),reasoning('accesibilidad','Explica sin depender del color','Una imagen marca en verde los índices válidos de un arreglo de tamaño tres y en rojo el índice tres. Redacta una descripción que transmita la misma información sin ver los colores.',['Nombra los índices explícitamente.','Incluye la razón del límite.'],'«El arreglo tiene tres posiciones, numeradas 0, 1 y 2. El índice 3 queda fuera porque al comenzar en cero el último índice es tamaño menos uno». Esta descripción transmite el contenido esencial sin depender de la imagen ni del color. Si además mostramos el ciclo i < 3, conectamos la representación visual con una condición verificable.')]),
'usaco-general-debugging-checklist':chapter('usaco-general-debugging-checklist',[
 ['Investiga por capas','Primero comprueba que el programa compile. Luego verifica que leyó los datos esperados, que las variables empiezan con valores definidos y que los ciclos visitan las posiciones correctas. Después revisa la idea matemática y los límites numéricos. Esta secuencia evita buscar una teoría complicada cuando el programa simplemente leyó n en el lugar equivocado. Anota la primera diferencia entre lo esperado y lo observado.'],
 ['Reduce el caso que falla','Si una lista de mil números produce un error, intenta conservar solo los elementos necesarios para reproducirlo. Para un máximo inicializado en cero, el caso de un solo número −5 ya muestra la falla. El ejemplo mínimo elimina ruido y hace visible una suposición falsa: el código suponía que existiría un valor no negativo. No cambies el programa y la entrada al mismo tiempo si quieres saber cuál cambio produjo el efecto.'],
 ['Una corrección necesita una nueva explicación','Después de corregir, vuelve a ejecutar el caso mínimo y los casos que antes funcionaban. Explica por qué el cambio arregla la causa: inicializar el máximo con el primer dato representa un candidato válido desde el comienzo. Agregar una condición especial solo para −5 no resuelve el problema general. Una lista de revisión ayuda a organizar hipótesis; no reemplaza entender qué afirmación era incorrecta.']
 ],[reasoning('minimo','Reduce una falla','Un programa que busca el máximo devuelve 0 para la lista −8, −3, −10. Propón el caso válido más pequeño que probablemente reproduzca el fallo y una hipótesis sobre su causa.',['Un solo dato negativo puede bastar.','Piensa en cómo se inicializó el máximo.'],'La lista de un elemento −3 debería devolver −3; si devuelve 0, probablemente el máximo comenzó en cero y solo se reemplaza por valores mayores. La corrección es iniciar con un elemento real cuando la lista es no vacía, o usar una estrategia que represente explícitamente que todavía no se ha leído ninguno. El caso mínimo explica la causa sin datos distractores.'),reasoning('revision','Revisa una corrección','Alguien arregla el error anterior agregando «si la entrada es −3, imprime −3». Diseña dos pruebas que muestren por qué no es una solución general.',['Cambia el valor negativo.','Prueba más de un dato.'],'Un solo −7 y la lista −9, −4 refutan el parche: las respuestas correctas son −7 y −4, pero el programa conservaría cero si no coincide con el caso especial. Una corrección general debe cambiar la representación inicial del máximo, no reconocer una entrada particular. Después se revisan también ceros, positivos y valores repetidos.')]),
'usaco-general-practicing':chapter('usaco-general-practicing',[
 ['Elige una dificultad que produzca información','Un ejercicio demasiado sencillo puede servir para automatizar lectura y formato; uno demasiado lejano puede consumir toda la sesión sin darte una idea nueva. Busca problemas donde entiendas el enunciado y puedas construir ejemplos, aunque todavía no tengas el método completo. Si necesitas ayuda, abre una pista por vez y vuelve a intentar. El objetivo es apropiarte de una observación, no proteger un contador de ejercicios hechos sin pistas.'],
 ['Reconstruye después de ver una solución','Leer una solución y pensar «era obvio» no garantiza poder producirla. Cierra la explicación y escribe con tus palabras la observación clave, una traza y la razón de corrección. Implementa desde cero después de un descanso breve o en otra sesión. Cambia un detalle del enunciado y pregunta si el método sigue funcionando. Esa variación distingue una comprensión flexible de una copia recordada.'],
 ['Lleva un registro breve y útil','Anota el tema, la dificultad concreta, la pista que desbloqueó el avance y una prueba importante. Un registro como «confundí valor con posición; probar repetidos» sirve para elegir el siguiente ejercicio. El tiempo invertido y la cantidad de envíos son datos, pero no sustituyen la calidad del razonamiento. Alterna práctica de un tema reciente con problemas de temas anteriores para aprender a elegir herramientas sin que el título revele la respuesta.']
 ],[reasoning('plan','Después de usar una pista','Usaste una pista para descubrir que había que ordenar los datos. Diseña dos actividades para comprobar que entendiste y no solamente imitaste la solución.',['Pregunta qué propiedad crea el orden.','Cambia una condición del problema.'],'Primero explicamos qué comparación se vuelve posible al ordenar y probamos una lista con repetidos. Después cambiamos el objetivo: si antes buscábamos valores adyacentes en orden, preguntamos si necesitamos conservar las posiciones originales. Implementar nuevamente sin consultar y justificar esa diferencia revela comprensión más sólida que volver a ejecutar el mismo código.'),reasoning('bitacora','Escribe un apunte útil','Tras fallar tres veces por usar int para una suma grande, redacta una nota de práctica que incluya causa, cálculo del máximo y regla para la siguiente sesión.',['Usa límites, no solo «int es pequeño».','La operación también debe realizarse en el tipo correcto.'],'«Sumaba hasta 100000 valores de hasta 1000000000; el total puede llegar a 100000000000000, fuera de int. Debo usar long long para el acumulador y revisar los operandos de productos. Antes de programar, calcularé la magnitud máxima de cada resultado intermedio». La nota transforma tres fallos similares en un procedimiento concreto de prevención.')]),
'usaco-general-contest-strategy':chapter('usaco-general-contest-strategy',[
 ['Lee buscando decisiones','En la primera pasada identifica qué pide cada problema, sus límites y si tienes una idea verificable. No confundas una historia larga con un algoritmo difícil. Un problema corto también puede exigir una observación profunda. Haz una estimación de riesgo: idea clara, implementación larga, límite dudoso o tema desconocido. Esa información permite elegir por dónde empezar sin dejar que el orden de presentación decida por ti.'],
 ['Guarda una base correcta','Si conoces una solución lenta para tamaños pequeños, puede ayudarte a comprender y comparar casos. En algunos concursos existen subtareas, pero su puntuación depende del reglamento; no asumas que siempre recibirás puntos parciales. Incluso sin subtareas, la versión sencilla puede funcionar como referencia de pruebas. Antes de optimizar, explica qué trabajo repetido eliminarás y por qué la respuesta no cambiará.'],
 ['Decide con evidencia durante el tiempo','Una señal de progreso es encontrar un contraejemplo, una propiedad o una implementación más clara. Repetir cambios al azar no lo es. Si te atoras, guarda el estado, escribe la duda y cambia temporalmente. En los minutos finales verifica formato, desbordamientos y casos pequeños; una mejora ambiciosa sin tiempo para revisar puede reemplazar una solución correcta por una incorrecta. Entrena estas decisiones en simulacros locales para conocer tu ritmo.']
 ],[reasoning('seleccion','Elige el siguiente paso','Quedan veinte minutos. Tienes una solución comprobada de A, una de B que falla un caso de frontera y una idea vaga de C. Propón un uso razonado del tiempo sin suponer puntuaciones parciales.',['Un fallo concreto ofrece una tarea delimitada.','Reserva una revisión final.'],'Conviene guardar A, investigar el caso mínimo que falla en B y reservar algunos minutos para revisar ambos. C puede recibir una breve exploración si B queda resuelto, pero una idea vaga tiene mayor incertidumbre. La estrategia depende de las reglas y del avance real; lo esencial es usar evidencia sobre lo que falta y no reiniciar trabajo ya confiable.'),reasoning('subtareas','No confundas práctica con puntuación','Una solución O(n²) funciona para n ≤ 1000, pero el problema permite n = 200000. Explica por qué puede ser útil durante el entrenamiento y por qué no debes prometer que será aceptada.',['La corrección y el costo se evalúan por separado.','El reglamento define si existen subtareas.'],'La solución puede servir para verificar casos pequeños y construir contraejemplos de una versión rápida. Sin embargo, para 200000 elementos el trabajo cuadrático puede ser enorme y exceder el tiempo. Solo habrá puntuación parcial si las reglas la contemplan y esos casos corresponden a una subtarea. Una herramienta de aprendizaje útil no es automáticamente una solución final aceptable.')]),
'usaco-general-resources-cp':chapter('usaco-general-resources-cp',[
 ['Usa una pregunta como filtro','Antes de abrir más material, formula qué necesitas: «no entiendo por qué ordenar permite revisar vecinos» o «no sé calcular el costo de este ciclo». Esa pregunta ayuda a encontrar el párrafo pertinente y a reconocer cuando ya tienes suficiente información para practicar. Acumular pestañas puede dar sensación de avance sin resolver la duda. La guía local presenta los conceptos y ejercicios principales para que una consulta adicional sea una opción.'],
 ['Evalúa un recurso con un ejemplo','Comprueba si define sus símbolos, muestra una entrada completa y justifica la respuesta. Intenta ejecutar su método con datos distintos. Si utiliza una herramienta que no conoces, identifica el requisito en lugar de asumir que toda la explicación está fuera de tu alcance. Una fuente avanzada puede ser correcta y aun así no ser la adecuada para tu siguiente paso. Nivel y precisión son criterios diferentes.'],
 ['Integra lo que aprendiste','Después de consultar algo, escribe una explicación propia y resuelve una variante pequeña. Si el recurso está en otro idioma, no es necesario empezar por él: puedes estudiar aquí la idea y usar después términos técnicos como referencia. Los nombres ingleses que aparezcan entre paréntesis sirven para reconocerlos, no como requisito lingüístico. La autonomía consiste en saber formular, comprobar y cerrar una pregunta, no en evitar cualquier consulta.']
 ],[reasoning('filtro','Elige una explicación adecuada','Dos recursos hablan de búsqueda binaria. Uno da veinte líneas de código sin requisitos; otro explica que la condición debe ser monótona y muestra un caso pequeño. ¿Cuál usarías primero y qué comprobarías después?',['Busca la condición que hace válido el método.','El código debe coincidir con la variante explicada.'],'Empezaría con el que define monotonicidad y permite trazar decisiones. Después comprobaría qué intervalo conserva, qué significa cada frontera y cuándo termina. El código corto puede servir como comparación posterior, pero sin sus condiciones sería fácil aplicarlo a una secuencia donde la respuesta no está ordenada.'),reasoning('pregunta','Convierte una duda vaga','Reescribe «no entiendo los grafos» en tres preguntas concretas que puedas responder por separado en una lección.',['Separa representación, recorrido y aplicación.','Cada pregunta debe permitir un ejemplo pequeño.'],'Podemos preguntar: «¿qué representan un vértice y una arista en un mapa de calles?», «¿cómo guardo los vecinos de cada vértice?» y «¿cómo sé si puedo llegar de A a B?». Cada pregunta tiene un ejemplo manejable y requisitos distintos. Resolverlas en ese orden construye una comprensión que una búsqueda demasiado amplia podría dispersar.')]),
'usaco-general-contests':chapter('usaco-general-contests',[
 ['Simulacro y práctica guiada tienen objetivos distintos','Durante una sesión guiada puedes consultar pistas y detenerte a estudiar una idea. En un simulacro, limita esas ayudas para observar qué puedes reconstruir bajo tiempo. Ambas modalidades son valiosas. Si haces todos los ejercicios con cronómetro desde el principio, quizá entrenes ansiedad sin haber construido herramientas; si nunca practicas con tiempo, no aprenderás a distribuirlo cuando sea necesario.'],
 ['Prepara un simulacro local completo','Elige tres ejercicios no resueltos de temas que ya estudiaste, fija una duración y prepara espacio para notas. Lee todos antes de programar. Guarda tus intentos y registra cuándo cambiaste de problema. Al terminar el tiempo, conserva ese resultado y luego abre una fase de aprendizaje sin cronómetro. No modifiques retrospectivamente la medición: distinguir qué sabías durante el ensayo permite decidir qué repasar.'],
 ['Revisa lo que una clasificación no muestra','Dos personas con el mismo número de respuestas correctas pueden necesitar trabajos diferentes: una conoce las ideas y falla índices; otra programa bien pero tarda en elegir un método. Mira causas, no solo posiciones. Los concursos externos son oportunidades opcionales y sus reglas pueden cambiar. Antes de participar consulta la información oficial vigente; puedes desarrollar la preparación de esta ruta sin depender de una plataforma externa.']
 ],[reasoning('simulacro','Diseña un ensayo equilibrado','Ya estudiaste condicionales, ciclos y ordenamiento. Propón tres tipos de ejercicio y una revisión posterior que permita distinguir errores de idea de errores de implementación.',['Incluye al menos un ejercicio que combines conceptos.','Guarda tus notas previas al código.'],'Podemos elegir clasificación por intervalos, conteo en una lista y una tarea que requiera ordenar antes de comparar. Guardamos la idea escrita y el código de cada uno. Si la idea explica correctamente el resultado pero el programa falla, revisamos implementación; si la idea misma contradice un ejemplo, estudiamos el razonamiento. Esta separación orienta la siguiente sesión.'),reasoning('comparar','Interpreta un resultado','En dos simulacros resuelves dos de tres ejercicios. En el segundo verificaste fronteras, cometiste menos errores y te atascaste en una idea nueva. ¿Hubo aprendizaje aunque el total sea igual?',['El conteo final no describe todo el proceso.','Identifica cambios observables.'],'Sí: reducir errores y mejorar la verificación son avances observables. El problema restante puede requerir una idea que todavía no se estudió, diferente de los fallos anteriores. La siguiente tarea es aprender esa observación y comprobar si puedes reconstruirla después. Comparar procesos evita que una cifra única oculte mejoras importantes.')]),
'usaco-general-olympiads':chapter('usaco-general-olympiads',[
 ['La ruta local y los eventos oficiales','Esta guía es un espacio de preparación para estudiantes de Morelos. Aprender aquí, guardar progreso o terminar una etapa no equivale a registrarse ni clasificarse automáticamente en una olimpiada. Los procesos oficiales establecen edades, categorías, fechas y etapas en sus convocatorias. Cuando llegue el momento de participar, revisa esas reglas vigentes con tu familia o docente; mientras tanto puedes entrenar todas las habilidades dentro de la plataforma.'],
 ['Qué construyes durante la preparación','Al principio transformas historias en operaciones y programas pequeños. Después reconoces patrones como ordenamiento, búsqueda y recorridos. En temas avanzados combinas estructuras y demostraciones. La preparación no consiste únicamente en aprender más nombres: también mejora tu capacidad de explicar, diseñar pruebas, administrar tiempo y pedir una ayuda concreta. Esas habilidades sirven aunque decidas no participar en un evento competitivo.'],
 ['Un equipo que aprende con autonomía','Puedes estudiar por tu cuenta y compartir después la explicación de un ejercicio. Cuando ayudes a alguien, pregunta qué entiende y ofrece una pista que preserve su trabajo. Compartir soluciones completas durante una evaluación puede violar sus reglas; durante entrenamiento, discutir razonamientos de forma acordada puede ser muy útil. Distingue siempre sesión de aprendizaje de evaluación individual y respeta las condiciones de cada actividad.']
 ],[reasoning('ruta-morelos','Separa preparación y registro','Una estudiante terminó Bronce y cree que ya está inscrita en la siguiente olimpiada. Explica qué demuestra ese avance y qué información necesita verificar fuera del registro de progreso.',['La plataforma conserva aprendizaje, no trámites oficiales.','Las condiciones las determina la convocatoria vigente.'],'Terminar Bronce indica que trabajó ciertos temas y ejercicios de la ruta. No acredita inscripción ni selección oficial. Debe verificar convocatoria, categoría, requisitos, fechas y procedimiento de registro con la organización correspondiente. Esa consulta administrativa es distinta de aprender algoritmos; puede seguir preparándose aquí mientras obtiene información del evento.'),reasoning('ayuda','Ofrece una pista responsable','Un compañero se atasca en contar valores mayores que un umbral. Durante una práctica libre, ¿cómo lo ayudarías sin sustituir su razonamiento? ¿Qué cambia si es una evaluación individual?',['Pregunta qué significa el contador tras cada paso.','Las reglas de una evaluación determinan qué ayuda se permite.'],'En práctica libre podemos pedirle una traza de tres valores y preguntarle cuándo debe aumentar el contador. Si hace falta, sugerimos una condición sin entregar de inmediato todo el programa. En una evaluación individual respetamos sus reglas y posponemos la ayuda hasta el cierre cuando no esté permitida. La intención de enseñar no elimina las condiciones de una evaluación.')]),
'usaco-general-usaco-faq':chapter('usaco-general-usaco-faq',[
 ['Por qué aparece USACO en esta ruta','USACO es una referencia conocida de programación competitiva y su guía pública organiza muchos temas por niveles. Nuestra ruta usa esa cobertura como referencia temática, pero añade inicio desde cero y explicaciones originales en español. Los nombres Bronce, Plata, Oro y Platino ayudan a organizar la dificultad; no son certificaciones emitidas por esta plataforma ni garantizan equivalencias con etapas de una competencia mexicana.'],
 ['Qué necesitas y qué es opcional','No necesitas una cuenta de USACO, resolver un concurso externo ni leer sus artículos para realizar las lecciones locales. Las fuentes permiten consultar el origen de la organización y ampliar lecturas cuando te interese. Si decides participar en concursos externos, revisa sus reglas actuales, idiomas disponibles y condiciones de elegibilidad. No asumimos aquí que esas condiciones sean permanentes ni que apliquen igual a estudiantes de distintos países.'],
 ['Usa los niveles como mapa flexible','Puedes repasar un tema sencillo después de haber estudiado uno avanzado. Un nivel agrupa herramientas, pero un problema particular puede combinar varias o exigir una observación inesperada. Si una etiqueta te intimida, vuelve a la entrada, la salida y los ejemplos. La pregunta útil es qué habilidad te falta para justificar el método, no si una clasificación te permite intentarlo. La práctica integrada te deja explorar sin trámites.']
 ],[reasoning('equivalencias','Evita una conclusión incorrecta','Alguien afirma: «Si terminé Oro aquí, ya tengo una medalla de una olimpiada». Explica la confusión y redacta una descripción precisa de lo que sí logró.',['Distingue etapa educativa de resultado oficial.','Describe habilidades verificables.'],'La etiqueta Oro nombra una etapa del material, no una medalla oficial. Una descripción precisa sería: «Estudié los temas de la etapa Oro y resolví sus ejercicios locales». Para afirmar un resultado de concurso hace falta participar según sus reglas y obtener ese resultado. Separar ambos evita atribuir a la plataforma una certificación que no otorga.'),reasoning('autonomia','Plan sin cuenta externa','Diseña una semana de preparación que no requiera registrarse en otro sitio ni conocer inglés. Incluye estudio, práctica y repaso.',['Usa capítulos, laboratorio y soluciones locales.','El repaso debe reconstruir una idea sin mirar.'],'Podemos estudiar dos capítulos de la ruta, ejecutar sus ejemplos, resolver los ejercicios integrados con pistas graduadas y dedicar otra sesión a repetir una solución desde cero. Al final hacemos un simulacro con ejercicios aún no resueltos. Anotamos dudas y volvemos a requisitos concretos. Las fuentes externas quedan disponibles para consulta futura, pero ninguna actividad depende de abrirlas.')]),
'usaco-general-usaco-monthlies':chapter('usaco-general-usaco-monthlies',[
 ['Qué aporta una práctica periódica','Resolver una colección nueva de problemas cada cierto tiempo permite observar cambios en comprensión, implementación y distribución del tiempo. Puedes reproducir esa idea con ejercicios locales: selecciona un grupo, fija un periodo y reserva una revisión posterior. No necesitas esperar una fecha oficial para entrenar de manera consistente. La regularidad ayuda a volver sobre lo aprendido antes de olvidarlo por completo.'],
 ['Simula sin confundir condiciones','Si usas un concurso archivado, anota qué reglas estás reproduciendo y qué ayudas permites. Un ensayo con soluciones abiertas mide algo distinto de uno individual. Para la práctica integrada basta elegir ejercicios nuevos, cerrar las pistas durante el tiempo acordado y abrirlas al terminar. No afirmes una equivalencia de nivel por un único ensayo: la dificultad y los temas de una colección pueden variar mucho.'],
 ['La revisión vale tanto como el intento','Clasifica cada problema en resuelto y explicado, resuelto con dudas, o pendiente. En los dos últimos, identifica la primera observación que faltó. Programa un nuevo intento después de estudiar esa idea; no repitas de memoria inmediatamente. Si decides participar en un evento de USACO, consulta sus fechas y reglas oficiales actuales. El nombre de esta lección describe un modelo de entrenamiento periódico, no una agenda garantizada.']
 ],[reasoning('periodicidad','Un plan de cuatro sesiones','Diseña cuatro sesiones alrededor de un pequeño simulacro: preparación, intento, revisión y repetición. Explica por qué no deben convertirse en cuatro copias del mismo código.',['Cada sesión debe tener una finalidad diferente.','La repetición comprueba recuperación de la idea.'],'La preparación repasa requisitos; el intento mide decisiones sin pistas; la revisión identifica y estudia las observaciones faltantes; la repetición reconstruye la solución con una entrada o variante nueva. Copiar el mismo código en todas las sesiones solo practica transcripción. Separar objetivos permite detectar qué cambió en nuestra comprensión.'),reasoning('resultados','Interpreta dos colecciones','Resuelves todos los ejercicios de una colección sobre arreglos y ninguno de otra sobre grafos. ¿Puedes concluir que empeoraste? ¿Qué datos necesitas?',['Las colecciones no miden necesariamente los mismos conocimientos.','Revisa requisitos y causas de los fallos.'],'No podemos concluirlo solo con el total. Necesitamos saber si ya estudiaste grafos, si entendiste los enunciados y dónde se detuvo cada intento. La segunda colección quizá explore habilidades nuevas. Un registro por tema y causa permite elegir el repaso; comparar cantidades sin considerar contenido puede producir una conclusión engañosa.')]),
'usaco-general-usaco-camp':chapter('usaco-general-usaco-camp',[
 ['Qué podemos adoptar de un campamento','Un campamento concentra explicaciones, práctica exigente y conversación sobre soluciones. Podemos adoptar su estructura sin reproducir un evento oficial: una sesión presenta una idea, otra propone problemas y otra revisa caminos alternativos. Lo importante es que cada actividad alimente a la siguiente. No necesitas jornadas agotadoras; para estudiantes que también tienen clases, la continuidad y el descanso ayudan a mantener la atención.'],
 ['Discute soluciones con evidencia','Cuando compares dos métodos, pregunta qué datos conservan, por qué funcionan y cuánto cuestan. «Mi código es más corto» no demuestra que sea mejor. Una solución clara puede facilitar revisar fronteras; otra puede ahorrar memoria necesaria para límites mayores. Mostrar un contraejemplo de manera respetuosa es una contribución al aprendizaje del grupo. Deja que quien propone una idea revise su argumento antes de reemplazarlo por el tuyo.'],
 ['Un minicampamento autónomo','Puedes organizar tres días: primero simulación y búsqueda exhaustiva; segundo ordenamiento y voraces; tercero problemas mezclados y revisión. Ajusta la selección a requisitos que ya dominas y usa los ejercicios locales. Después escribe qué herramientas reconociste sin ayuda y cuáles solo usaste cuando el título las sugería. Esa diferencia muestra qué transferencias necesitas practicar antes de avanzar a problemas más abiertos.']
 ],[reasoning('agenda','Diseña tres bloques de estudio','Dispones de una tarde con tres bloques de cuarenta minutos y pausas entre ellos. Propón un formato inspirado en un campamento para estudiar búsqueda exhaustiva.',['Combina explicación, intento y discusión.','No llenes todo el tiempo con lectura.'],'Un primer bloque puede trazar y justificar una enumeración pequeña; el segundo intenta dos variantes con pistas cerradas; el tercero compara soluciones y estudia un caso que falló. Las pausas separan esfuerzos y permiten volver con atención. La selección debe ser compatible con conocimientos actuales; acumular temas avanzados sin práctica no reproduce el valor de un campamento.'),reasoning('comparacion','Compara dos soluciones','Dos estudiantes generan parejas: uno usa todos los i y j y descarta i >= j; otro empieza j en i + 1. Explica qué tienen en común y qué diferencia conviene discutir.',['Ambos pueden enumerar las mismas parejas válidas.','Cuenta iteraciones y revisa claridad.'],'Ambos pueden ser correctos si el primero descarta adecuadamente los casos inválidos. El segundo expresa directamente i < j y evita revisar parejas que nunca sirven. Los dos tienen costo O(n²), pero difieren en constantes y en cómo hacen visible la ausencia de duplicados. La discusión útil incluye corrección, costo y facilidad de revisión, no solo longitud del código.')]),
'usaco-general-resources-usa':chapter('usaco-general-resources-usa',[
 ['Adapta el contenido, no las reglas por suposición','Un material de otro país puede explicar un algoritmo universal y al mismo tiempo describir un proceso de selección particular. La suma de prefijos funciona igual en Morelos; las edades, categorías o fechas de un concurso no se transfieren automáticamente. Separa las ideas técnicas de la información administrativa. Esta ruta conserva una progresión amplia de algoritmos y la presenta con ejemplos propios en español.'],
 ['Construye un vocabulario después de entender','Puedes reconocer que prefix sum significa suma de prefijos o que greedy se refiere a una estrategia voraz, pero primero necesitas entender qué hace el método. Asociar ambos nombres después ayuda a leer referencias futuras. No uses el término inglés como explicación: decir «haz greedy» no justifica ninguna decisión. Un vocabulario bilingüe es una herramienta opcional que se construye sobre una idea ya comprendida.'],
 ['Comprueba una adaptación con estudiantes reales','Al adaptar un ejercicio, define unidades, nombres y convenciones que el lector pueda interpretar. No cambies una condición matemática sin revisar la solución. Si conviertes distancias o monedas, asegúrate de que los límites y ejemplos sigan coherentes. Lo local debe facilitar entender la tarea; no hace falta agregar una historia larga a una operación sencilla. La claridad se verifica cuando alguien puede resolver y explicar sin consultar el texto original.']
 ],[reasoning('adaptar','Adapta sin alterar el problema','Un ejercicio cuenta formas de elegir dos estudiantes distintos de un grupo. Cambias los nombres y el lugar a una escuela de Morelos. ¿Qué condiciones matemáticas debes conservar?',['Distingue pareja de orden de selección.','No permitas elegir a la misma persona dos veces.'],'Debemos conservar que se eligen dos personas diferentes y aclarar si el orden no importa. Cambiar nombres o ubicación no altera el conteo n(n − 1)/2. Si introdujéramos roles diferentes, como capitán y suplente, el orden sí importaría y el resultado cambiaría a n(n − 1). Una adaptación de contexto debe cuidar esas relaciones.'),reasoning('vocabulario','Explica antes de traducir','Explica en español qué conserva una suma de prefijos y después escribe cómo usarías su nombre inglés como ayuda opcional, sin convertirlo en requisito.',['Define qué representa P[i].','Un nombre no sustituye la fórmula.'],'Definimos P[i] como la suma de los primeros i valores, con P[0] = 0. Entonces sumar posiciones l hasta r puede obtenerse restando dos prefijos adecuados. Después podemos anotar que esta herramienta también se llama prefix sum para reconocerla en referencias. La definición y el ejemplo permiten aprender sin saber inglés; el nombre adicional solo facilita consultas futuras.')]),
};
